 "findings": [
  {
   "Finding": "Backlog improved after 2021",
   "Assessment": "Strong",
   "Evidence": "Open/closed ratio 4.33 (2020), 4.43 (2021), 1.35 (2022), 1.01 (2023), 1.21 (2024); national 3.74, 3.60, 3.13, 3.27, 3.43",
   "How it helps the complaint": "Shows a clear turning point and provides a benchmark for whether older individual files benefited from the improvement",
   "Caution": "A lower ratio can result from more closures; it does not establish that closures were correct",
   "Next test": "Obtain aged cases and closure-ground detail"
  },
  {
   "Finding": "2023 closure activity was high",
   "Assessment": "Strong",
   "Evidence": "380 cases closed versus 230 investigated; 385 open at year-end",
   "How it helps the complaint": "Supports asking how older files were selected, reviewed and closed during the clearance period",
   "Caution": "NOAC does not identify individual cases or the quality of closure decisions",
   "Next test": "Match anonymised closures to age and reason"
  },
  {
   "Finding": "Enforcement category share was high",
   "Assessment": "Strong",
   "Evidence": "71.05% of 2023 closures in NOAC enforcement-proceedings category versus 41.30% nationally",
   "How it helps the complaint": "Useful comparator for whether Dundrum handling was consistent with normal escalation and compliance practice",
   "Caution": "Category includes compliance after warning letter/notice, prosecution and injunction; do not call all of these court actions",
   "Next test": "Request detailed outcome codes"
  },
  {
   "Finding": "Appeal confirmation was volatile",
   "Assessment": "Strong",
   "Evidence": "Below national in 2020 and 2023; above in 2021, 2022 and 2024",
   "How it helps the complaint": "Prevents a weak allegation of persistent decision-quality failure and directs attention to specific files/quality controls",
   "Caution": "Annual counts can be small; confirmation with variation is included",
   "Next test": "Separate confirmation with variation in raw case list"
  },
  {
   "Finding": "Planning spend remained below national",
   "Assessment": "Strong",
   "Evidence": "€24.03–€28.28 per capita in 2020–2024 versus €31.47–€38.47 nationally",
   "How it helps the complaint": "Justifies asking whether staffing, vacancies and caseload affected timeliness or record quality",
   "Caution": "Cost alone cannot distinguish efficiency from under-resourcing or different service mix",
   "Next test": "Compare WTE, vacancies, workload and service outcomes"
  },
  {
   "Finding": "Best-supported complaint framing",
   "Assessment": "Analytical conclusion",
   "Evidence": "Published aggregate indicators plus Dundrum case chronology",
   "How it helps the complaint": "Focus on delay, classification/closure transparency, cross-department coordination, consistency and reasons in the individual case",
   "Caution": "Published data does not support saying the whole department was generally ineffective in 2022–2024",
   "Next test": "Test the case against policy and matched anonymised cases"
  },
  {
   "Finding": "Known data limitation",
   "Assessment": "Strong",
   "Evidence": "NOAC combines trivial, statute-barred and exempt closures",
   "How it helps the complaint": "Supports a precise request for disaggregated closure grounds without duplicating the existing FOI/AIE unless gaps remain",
   "Caution": "Do not infer statute-barred cases from the combined percentage",
   "Next test": "Review existing disclosures first, then draft a narrow gap request only if required"
  }
 ],
