   "Priority": "High",
   "Current factual support": "DHG submitted a detailed dossier; ACP considered identified internal changes but found the referral works did not materially affect protected-structure character; OPR recommended evaluating dedicated heritage expertise.",
   "Evidence IDs": "E014-E016; E019; E039",
   "What remains unproved / pending": "Issue-by-issue inspection matrix, authorised/retained status, conservation assessment, visit records, photos and specialist input.",
   "Administrative concern to test": "Whether every reported work was separately identified, inspected and assigned a planning/heritage basis rather than treated as one undifferentiated allegation.",
   "Injustice / public-interest risk": "Potential omission of works from assessment and inability to determine what was inspected, authorised, retained or unresolved.",
   "Remedy sought": "Produce an issue-by-issue response and independent conservation review of any work not previously assessed.",
