   "Administrative concern to test": "Whether records support reproducible decisions, consistent classifications and meaningful management/member oversight.",
   "Injustice / public-interest risk": "Risk of inconsistent or untraceable outcomes even where aggregate performance appears satisfactory.",
   "Remedy sought": "Confirm implementation of OPR recommendations 1, 8, 9 and 11; audit the relevant files and report corrective actions.",
   "Primary route": "Council corporate complaint; Ombudsman; OPR systems review",
